## Solution
```cpp
class Solution {
public:
    vector<vector<string>> findSequences(string beginWord, string endWord,
                                         vector<string> &wordList) {

        unordered_set<string> dict(wordList.begin(), wordList.end());
        vector<vector<string>> ans;
        queue<vector<string>> q;

        q.push({beginWord});

        auto getNext = [&](string word) {
            vector<string> next;
            for (int i = 0; i < word.size(); i++) {
                char old = word[i];
                for (char c = 'a'; c <= 'z'; c++) {
                    if (c == old) continue;
                    word[i] = c;
                    if (dict.count(word)) next.push_back(word);
                }
                word[i] = old;
            }
            return next;
        };

        while (!q.empty()) {
            int sz = q.size();
            unordered_set<string> used;

            while (sz--) {
                auto path = q.front(); q.pop();
                string last = path.back();

                if (last == endWord) {
                    if (ans.empty() || ans[0].size() == path.size())
                        ans.push_back(path);
                }

                for (auto &next : getNext(last)) {
                    path.push_back(next);
                    q.push(path);
                    used.insert(next);
                    path.pop_back();
                }
            }

            for (auto &w : used) dict.erase(w);

            if (!ans.empty()) break;   // stopping at shortest and EXIT ::
        }

        return ans;
    }
};

```

