class Solution{
public:
    vector<vector<string>> findSequences(string beginWord, string endWord,
                                         vector<string> &wordList) {

        vector<vector<string>> ans;
        unordered_set<string> st(wordList.begin(), wordList.end());

        if(st.find(endWord) == st.end())
            return ans;

        queue<vector<string>> q;
        q.push({beginWord});

        int level = 1;
        int minLevel = INT_MAX;

        vector<string> usedOnLevel;

        while(!q.empty()){
            vector<string> temp = q.front();
            q.pop();

            // If we moved to next level
            if(temp.size() > level){
                level = temp.size();

                for(string word : usedOnLevel)
                    st.erase(word);

                usedOnLevel.clear();

                if(level > minLevel)
                    break;
            }

            string word = temp.back();

            if(word == endWord){
                if(temp.size() <= minLevel){
                    minLevel = temp.size();
                    ans.push_back(temp);
                }
                continue;
            }

            for(int i = 0; i < word.size(); i++){
                string newWord = word;
                for(char ch = 'a'; ch <= 'z'; ch++){
                    newWord[i] = ch;

                    if(st.count(newWord)){
                        vector<string> newPath = temp;
                        newPath.push_back(newWord);
                        q.push(newPath);
                        usedOnLevel.push_back(newWord);
                    }
                }
            }
        }

        return ans;
    }
};

```

